class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // In .NET 9, empty env vars are no longer treated as unset (returns "" not null).
        // Use !Exists check to distinguish "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val is null && !EnvironmentVariableExists("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    private static bool EnvironmentVariableExists(string name)
    {
        // GetEnvironmentVariable returns null only when truly not set in .NET 9.
        // An empty string means it was explicitly set to "".
        return Environment.GetEnvironmentVariable(name) is not null;
    }
}

